cd /workspace && node -e "
const XLSX = require('xlsx');
const docx = require('docx');
const fs = require('fs');

// --- Read data ---
const wb = XLSX.readFile('/workspace/testbed/data/order_summary.xlsx');
const data = XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]]);

// --- Analysis ---
const totalOrders = data.length;
const confirmed = data.filter(r => r.Status === 'confirmed');
const cancelled = data.filter(r => r.Status === 'cancelled');
const totalRevenue = data.reduce((s, r) => s + r['Total Paid'], 0);
const confirmedRevenue = confirmed.reduce((s, r) => s + r['Total Paid'], 0);
const cancelledRevenue = cancelled.reduce((s, r) => s + r['Total Paid'], 0);
const avgOrderValue = (confirmedRevenue / confirmed.length).toFixed(2);

// Customer breakdown
const custMap = {};
data.forEach(r => {
  if (!custMap[r.Customer]) custMap[r.Customer] = { orders: 0, revenue: 0, confirmed: 0, cancelled: 0 };
  custMap[r.Customer].orders++;
  custMap[r.Customer].revenue += r['Total Paid'];
  if (r.Status === 'confirmed') custMap[r.Customer].confirmed++;
  else custMap[r.Customer].cancelled++;
});
const topCustomers = Object.entries(custMap).sort((a,b) => b[1].revenue - a[1].revenue);

// Product frequency
const prodCount = {};
data.forEach(r => {
  r.Items.split(', ').forEach(item => {
    prodCount[item] = (prodCount[item] || 0) + 1;
  });
});
const topProducts = Object.entries(prodCount).sort((a,b) => b[1] - a[1]);

// Date breakdown
const dateMap = {};
data.forEach(r => {
  if (!dateMap[r.Date]) dateMap[r.Date] = { orders: 0, revenue: 0 };
  dateMap[r.Date].orders++;
  dateMap[r.Date].revenue += r['Total Paid'];
});

// --- Build Word Document ---
const { Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell, WidthType, HeadingLevel, BorderStyle, AlignmentType } = docx;

function headerCell(text) {
  return new TableCell({
    children: [new Paragraph({ children: [new TextRun({ text, bold: true, font: 'Calibri', size: 20 })], alignment: AlignmentType.CENTER })],
    shading: { fill: '2E4057' },
    // white text on dark bg
  });
}
function cell(text, align) {
  return new TableCell({
    children: [new Paragraph({ children: [new TextRun({ text: String(text), font: 'Calibri', size: 20 })], alignment: align || AlignmentType.LEFT })],
  });
}

const doc = new Document({
  sections: [{
    properties: {},
    children: [
      // Title
      new Paragraph({
        children: [new TextRun({ text: 'Order Summary Analysis', bold: true, font: 'Calibri', size: 40, color: '2E4057' })],
        heading: HeadingLevel.TITLE,
        spacing: { after: 200 },
      }),
      new Paragraph({
        children: [new TextRun({ text: 'Data Source: data/order_summary.xlsx  •  Generated: ' + new Date().toISOString().slice(0,10), font: 'Calibri', size: 20, italics: true, color: '888888' })],
        spacing: { after: 400 },
      }),

      // --- 1. Overview ---
      new Paragraph({ text: '1. High-Level Overview', heading: HeadingLevel.HEADING_1, spacing: { before: 300, after: 200 } }),
      new Paragraph({ children: [
        new TextRun({ text: 'Total Orders: ', bold: true, font: 'Calibri', size: 22 }),
        new TextRun({ text: String(totalOrders), font: 'Calibri', size: 22 }),
      ], spacing: { after: 80 } }),
      new Paragraph({ children: [
        new TextRun({ text: 'Confirmed: ', bold: true, font: 'Calibri', size: 22 }),
        new TextRun({ text: confirmed.length + ' (' + (confirmed.length/totalOrders*100).toFixed(1) + '%)', font: 'Calibri', size: 22 }),
        new TextRun({ text: '    Cancelled: ', bold: true, font: 'Calibri', size: 22 }),
        new TextRun({ text: cancelled.length + ' (' + (cancelled.length/totalOrders*100).toFixed(1) + '%)', font: 'Calibri', size: 22 }),
      ], spacing: { after: 80 } }),
      new Paragraph({ children: [
        new TextRun({ text: 'Total Revenue (all orders): ', bold: true, font: 'Calibri', size: 22 }),
        new TextRun({ text: '\$' + totalRevenue.toLocaleString(), font: 'Calibri', size: 22 }),
      ], spacing: { after: 80 } }),
      new Paragraph({ children: [
        new TextRun({ text: 'Confirmed Revenue: ', bold: true, font: 'Calibri', size: 22 }),
        new TextRun({ text: '\$' + confirmedRevenue.toLocaleString(), font: 'Calibri', size: 22 }),
        new TextRun({ text: '    Lost to Cancellations: ', bold: true, font: 'Calibri', size: 22 }),
        new TextRun({ text: '\$' + cancelledRevenue.toLocaleString(), font: 'Calibri', size: 22 }),
      ], spacing: { after: 80 } }),
      new Paragraph({ children: [
        new TextRun({ text: 'Average Confirmed Order Value: ', bold: true, font: 'Calibri', size: 22 }),
        new TextRun({ text: '\$' + avgOrderValue, font: 'Calibri', size: 22 }),
      ], spacing: { after: 300 } }),

      // --- 2. Orders by Date ---
      new Paragraph({ text: '2. Orders by Date', heading: HeadingLevel.HEADING_1, spacing: { before: 300, after: 200 } }),
      new Table({
        width: { size: 100, type: WidthType.PERCENTAGE },
        rows: [
          new TableRow({ children: [headerCell('Date'), headerCell('Orders'), headerCell('Revenue')] }),
          ...Object.entries(dateMap).sort().map(([date, v]) =>
            new TableRow({ children: [cell(date), cell(String(v.orders), AlignmentType.CENTER), cell('\$' + v.revenue, AlignmentType.RIGHT)] })
          ),
        ],
      }),

      // --- 3. Customer Breakdown ---
      new Paragraph({ text: '3. Customer Breakdown', heading: HeadingLevel.HEADING_1, spacing: { before: 400, after: 200 } }),
      new Table({
        width: { size: 100, type: WidthType.PERCENTAGE },
        rows: [
          new TableRow({ children: [headerCell('Customer'), headerCell('Orders'), headerCell('Confirmed'), headerCell('Cancelled'), headerCell('Revenue')] }),
          ...topCustomers.map(([name, v]) =>
            new TableRow({ children: [
              cell(name), cell(String(v.orders), AlignmentType.CENTER), cell(String(v.confirmed), AlignmentType.CENTER),
              cell(String(v.cancelled), AlignmentType.CENTER), cell('\$' + v.revenue, AlignmentType.RIGHT),
            ] })
          ),
        ],
      }),

      // --- 4. Most Popular Products ---
      new Paragraph({ text: '4. Most Popular Products', heading: HeadingLevel.HEADING_1, spacing: { before: 400, after: 200 } }),
      new Table({
        width: { size: 100, type: WidthType.PERCENTAGE },
        rows: [
          new TableRow({ children: [headerCell('Product'), headerCell('Appearances')] }),
          ...topProducts.map(([name, count]) =>
            new TableRow({ children: [cell(name), cell(String(count), AlignmentType.CENTER)] })
          ),
        ],
      }),

      // --- 5. Key Insights ---
      new Paragraph({ text: '5. Key Insights', heading: HeadingLevel.HEADING_1, spacing: { before: 400, after: 200 } }),
      new Paragraph({ children: [new TextRun({ text: '• The cancellation rate is ' + (cancelled.length/totalOrders*100).toFixed(1) + '% (' + cancelled.length + ' of ' + totalOrders + ' orders). All cancellations belong to just 2 customers: Maya Chen (2) and Jordan Alvarez (1).', font: 'Calibri', size: 22 })], spacing: { after: 100 } }),
      new Paragraph({ children: [new TextRun({ text: '• Maya Chen is the most active customer with ' + custMap['Maya Chen'].orders + ' orders totalling \$' + custMap['Maya Chen'].revenue + ', though 2 of those were cancelled.', font: 'Calibri', size: 22 })], spacing: { after: 100 } }),
      new Paragraph({ children: [new TextRun({ text: '• LogiTech Wireless Mouse M310 is the best-selling product, appearing in ' + prodCount['LogiTech Wireless Mouse M310'] + ' orders.', font: 'Calibri', size: 22 })], spacing: { after: 100 } }),
      new Paragraph({ children: [new TextRun({ text: '• OXO SoftWorks 3-Piece Mixing Bowl Set is the second most popular, appearing in ' + prodCount['OXO SoftWorks 3-Piece Mixing Bowl Set'] + ' orders.', font: 'Calibri', size: 22 })], spacing: { after: 100 } }),
      new Paragraph({ children: [new TextRun({ text: '• The bulk of orders (' + dateMap['2026-09-02'].orders + ') were placed on 2026-09-02, with only ' + (dateMap['2026-09-04']?.orders || 0) + ' orders on 2026-09-04.', font: 'Calibri', size: 22 })], spacing: { after: 100 } }),
      new Paragraph({ children: [new TextRun({ text: '• Average confirmed order value is \$' + avgOrderValue + ', suggesting a healthy basket size with multi-item purchases common.', font: 'Calibri', size: 22 })], spacing: { after: 100 } }),
    ],
  }],
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync('/workspace/data/order_analysis.docx', buffer);
  console.log('✅ Word document saved to /workspace/data/order_analysis.docx');
  console.log('   File size: ' + (buffer.length / 1024).toFixed(1) + ' KB');
});
"
